-- =====================================================================
-- Session 499c migration — 2026-11-13 — canon / Matthew 15:21–28 — the Canaanite-woman thread rewritten on Yoshi's reading:
-- the woman is a sheep of the scattered house (seed revealed, Matthew 15:22, 15:24); the bread is withheld because the divorced house cannot be
-- taken back until the husband's death (Jeremiah 3:8; Deuteronomy 24:4; Romans 7:2–4; Mark 7:27 "first"); the sending widens after the death.
-- Thread 30911 (matthew-15-the-canaanite-woman-the-lost-sheep-first-the-stranger-grafted-isaiah-56-psalm-22-1-kings-17): title + summary rewritten (slug kept). 7 cards rewritten in place with their member notes
-- (four S1xx cards rebuilt Come-and-See: 124214 124215 124216 124217; three S499 cards given the reason: 2876 177460 3520).
-- Written and read on Claude Fable 5.1; every note composed by script (target verse whole from parsed/canon.json, Matthew verse whole from the
-- Nov 13 20:11 read-back). Guards RAISE before any write if the live data moved. Idempotent. Nothing deleted, no card re-pointed.
-- =====================================================================
BEGIN;
CREATE TEMP TABLE s499c_cards (id bigint, src_ch int, src_vn int, src_text text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s499c_cards VALUES
(124214,15,24,$n$But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).$n$,'isaiah',56,8,$n$*Adonai Yahuah (The Lord GOD) which gathereth the outcasts of Yashar'el (Israel) saith, Yet will I gather others to him, beside those that are gathered unto him* (Isaiah 56:8). The order is Isaiah's own: the outcasts of Yashar'el gathered FIRST, and then *others beside* — the stranger brought in. *I am not sent but unto the lost sheep* is the first half of that promise, not the cancelling of the second.$n$,$n$Isaiah 56:8 — *Adonai Yahuah (The Lord GOD) which gathereth the outcasts of Yashar'el (Israel) saith, Yet will I gather others to him, beside those that are gathered unto him.* *But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24) Isaiah's order is the order of this coast. The outcasts of Yashar'el (Israel) are gathered, and *others* are gathered to him *beside those that are gathered unto him*: the house already home, and the scattered house still to be brought. When he says he is sent only to the lost sheep, that second gathering is what he is naming, and the woman is of it.$n$,30911,$n$Isaiah 56:8 — *gathereth the outcasts of Yashar'el... Yet will I gather others to him, beside* — the children first, the stranger beside.$n$,$n$Isaiah 56:8 — *Adonai Yahuah (The Lord GOD) which gathereth the outcasts of Yashar'el (Israel) saith, Yet will I gather others to him, beside those that are gathered unto him.* The outcasts of Yashar'el (Israel) gathered, and others gathered to him beside them, the two houses in Isaiah's order.$n$),
(124215,15,27,$n$And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters’ table.$n$,'isaiah',56,6,$n$*Also the sons of the stranger, that join themselves to Yahuah (LORD), to serve him, and to love the name of Yahuah (LORD)... every one that keepeth the sabbath from polluting it, and taketh hold of my covenant* (Isaiah 56:6). The Canaanite woman is this very stranger joined to Yahuah — pleading for the crumbs, taking hold by faith. Israel is never cast off; the stranger is grafted in beside her.$n$,$n$Isaiah 56:6 — *Also the sons of the stranger, that join themselves to Yahuah (LORD), to serve him, and to love the name of Yahuah (LORD), to be his servants, every one that keepeth the sabbath from polluting it, and taketh hold of my covenant;* *And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters’ table.* (Matthew 15:27) Isaiah's *sons of the stranger* are the ones who say Yahuah (the LORD) *hath utterly separated me from his people* (Isaiah 56:3), the house made strangers by the putting away. The woman at the table's edge is one of them, taking hold of the covenant from outside the room, keeping the order and asking for the crumbs. Isaiah says such are brought to his holy mountain.$n$,30911,$n$Isaiah 56:6 — *the sons of the stranger, that join themselves to Yahuah* — the woman joining herself by faith, grafted in beside Israel.$n$,$n$Isaiah 56:6 — *the sons of the stranger, that join themselves to Yahuah (LORD).* The sons of the stranger who join themselves to Yahuah (the LORD), the house made strangers by exile and brought home to his mountain.$n$),
(124216,15,28,$n$Then Yahusha (Jesus) answered and said unto her, O woman, great is your faith: be it unto you even as you will. And her daughter was made whole from that very hour.$n$,'psalms',22,27,$n$*All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee* (Psalm 22:27). The believing woman of Canaan is a firstfruit of this promise — the kindreds of the nations turning to the Elohim of Yashar'el. The children's bread is enough that the dogs may eat the crumbs and live.$n$,$n$Psalm 22:27 — *All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee.* *Then Yahusha (Jesus) answered and said unto her, O woman, great is your faith: be it unto you even as you will. And her daughter was made whole from that very hour.* (Matthew 15:28) This is the psalm of the cross, *why hast thou forsaken me* (Psalm 22:1), and the turning of *all the ends of the world* comes in it after the suffering, not before. They *remember*, which is what a people does who once knew him. What she asked for on this coast before his death, the psalm sets on the far side of it.$n$,30911,$n$Psalm 22:27 — *all the kindreds of the nations shall worship before thee* — the believing woman a firstfruit of the nations turning.$n$,$n$Psalm 22:27 — *All the ends of the world shall remember and turn unto Yahuah (LORD).* The ends of the world remember and turn, in the psalm of the cross, after the suffering and not before.$n$),
(124217,15,22,$n$And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, you Son of David; my daughter is grievously vexed with a devil.$n$,'1-kings',17,9,$n$*Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee* (1 Kings 17:9). A gentile widow of Sidon once fed Elijah and saw her dead son raised — the same coasts of Tyre and Sidon where this woman cries out. The faith of the stranger in the borders of Sidon is no new thing in the library.$n$,$n$1 Kings 17:9 — *Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee.* *And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, you Son of David; my daughter is grievously vexed with a devil.* (Matthew 15:22) The word of Yahuah (the LORD) sent Elijah to a widow of Zidon, on this same coast, and she was already commanded to sustain him before he arrived. The word reached her first. Yahusha (Jesus) walks onto the same coast and a woman there already knows him for *thou Son of David* (Matthew 15:22). Twice the sheep on this coast heard before the shepherd came.$n$,30911,$n$1 Kings 17:9 — the Sidonian widow who fed Elijah and saw her son raised — the faith of the stranger in these coasts is no new thing.$n$,$n$1 Kings 17:9 — *Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee.* A widow of Zidon commanded to sustain Elijah before he came, the sheep on this coast hearing first.$n$),
(2876,15,24,$n$But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).$n$,'matthew',28,19,$n$Matthew 28:19 — *Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* *But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24) Before the cross he says he is sent only to *the lost sheep of the house of Yashar'el (Israel)*, and after it the disciples are sent to teach *all nations*. The sending widens in place and not in people, for the sheep were scattered into every nation and the word has to go where they are.$n$,$n$Matthew 28:19 — *Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* *But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24) Before his death he says he is sent only to *the lost sheep of the house of Yashar'el (Israel)*, and the twelve were told *go not into the way of the Gentiles* (Matthew 10:5). After it they are sent to *all nations*. The children first, then the dogs; the sending widens in place and not in people, because the sheep were scattered into every nation and the death that frees the divorced house has now been died.$n$,221,$n$Matthew 28:19 — *Go ye therefore, and teach all nations.* The sending after the cross goes out to every nation, the places the lost sheep were scattered to, and not to a new kind of people.$n$,$n$Matthew 28:19 — *Go ye therefore, and teach all nations.* After the death and rising the sending goes to all nations, where the scattered sheep are, the second half of the order he kept on this coast.$n$),
(177460,15,24,$n$But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).$n$,'romans',11,25,$n$Romans 11:25 — *For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.* *But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24) The sheep of the house of Yashar'el (Israel) are scattered, and the woman of Canaan is one of them, called by the name of the coast she was scattered to. What Paul calls *the fulness of the Gentiles* is those same sheep found in every place they were driven and gathered home, not strangers added to the house.$n$,$n$Romans 11:25 — *For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.* *But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24) The sheep of the house of Yashar'el (Israel) are scattered, and the woman of Canaan is one of them, called by the name of the coast she was scattered to, *not my people* (Hosea 1:9) until the hearing shows what she is. What Paul calls *the fulness of the Gentiles* is those same sheep found in every place they were driven and gathered home after the death that frees them, not strangers added to the house.$n$,221,$n$Romans 11:25 — *blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.* Blindness in part to Yashar'el (Israel) until the fulness of the Gentiles comes in, the lost sheep found in every place they were scattered.$n$,$n$Romans 11:25 — *until the fulness of the Gentiles be come in.* The fulness of the Gentiles is the scattered house gathered home, the sheep he was sent to found where they were driven.$n$),
(3520,15,27,$n$And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters’ table.$n$,'matthew',8,10,$n$Matthew 8:10 — *When Yahusha (Jesus) heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Yashar'el (Israel).* *And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters’ table.* (Matthew 15:27) She answers with *Truth*, taking the order of the house as it is, and still asks for what falls from the table. The centurion did the same, *I am not worthy that thou shouldest come under my roof* (Matthew 8:8), and he marvelled at both. Neither argues the order, and both ask from inside it.$n$,$n$Matthew 8:10 — *When Yahusha (Jesus) heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Yashar'el (Israel).* *And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters’ table.* (Matthew 15:27) She answers with *Truth*, taking the order of the house as it is, the children first and the crumbs for the dogs, and still asks for what falls from the table. The centurion did the same, *I am not worthy that thou shouldest come under my roof* (Matthew 8:8), and he marvelled at both. Neither argues the order, because it was not yet their time, and both ask from inside it.$n$,30911,$n$Matthew 8:10 — *When Yahusha (Jesus) heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Yashar'el (Israel).* The centurion's lowly asking and the faith Yahusha (Jesus) marvelled at, answering the woman's own low asking at the table.$n$,$n$Matthew 8:10 — *I have not found so great faith, no, not in Yashar'el (Israel).* The centurion's lowly asking and the faith Yahusha (Jesus) marvelled at, the same faith the woman shows under the order of the table.$n$);
CREATE TEMP TABLE s499c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s499c_thread VALUES (30911, 'matthew-15-the-canaanite-woman-the-lost-sheep-first-the-stranger-grafted-isaiah-56-psalm-22-1-kings-17', $n$The lost sheep of Israel first, then the believing stranger — the Canaanite woman (Isaiah 56; Psalm 22; 1 Kings 17)$n$, $n$The lost sheep first — the woman of Canaan, the divorced house, and the children's bread (Deuteronomy 24; Hosea 2; Mark 7)$n$, $n$A woman of Canaan cries out in the coasts of Tyre and Sidon, *Have mercy on me, O Yahuah (Lord), thou Son of David*, and Yahusha says, *I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* This is not Israel cast off and the stranger put in her place — it is the order of the prophets, the children FIRST. Isaiah set it down exactly so: *Adonai Yahuah (The Lord GOD) which gathereth the outcasts of Yashar'el (Israel) saith, Yet will I gather others to him, beside those that are gathered unto him* (Isaiah 56:8) — the outcasts of Yashar'el gathered, and then *others beside.* And who are the others? *Also the sons of the stranger, that join themselves to Yahuah (LORD), to serve him, and to love the name of Yahuah (LORD)... and taketh hold of my covenant* (Isaiah 56:6) — the very woman, joining herself by faith, pleading for the crumbs that fall from the children's table. *O woman, great is thy faith.* She is a firstfruit of the psalm's great promise: *All the ends of the world shall remember and turn unto Yahuah (LORD): and all the kindreds of the nations shall worship before thee* (Psalm 22:27). Nor is the faith of a gentile woman in these coasts a new thing — *Arise, get thee to Zarephath, which belongeth to Zidon... behold, I have commanded a widow woman there to sustain thee* (1 Kings 17:9): a Sidonian widow once fed Elijah and saw her son raised. The children's bread is so abundant that the dogs eat the crumbs and live. Israel is never disinherited; the stranger is grafted in beside her — two houses and the nations, gathered home.$n$, $n$It ain't new. A woman cries after him on the coast of Tyre and Sidon, and the disciples want her sent away. His answer is to them, and it tells them who she is:

*But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24)

That was his whole errand. He had given the twelve the same boundary before he ever met her:

*But go rather to the lost sheep of the house of Yashar'el (Israel).* (Matthew 10:6)

And she is not a stranger to the house. Hear what she calls him:

*And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Adonai (Lord), thou Son of David; my daughter is grievously vexed with a devil.* (Matthew 15:22)

*Son of David* is the covenant word to David's house in the mouth of a woman on a Canaanite coast. She knew whose house the king came from, and she worshipped him. The sheep hear the voice because they are sheep, and Hosea had already named the place where such sheep would be found:

*Then said Elohim (God), Call his name Lo-ammi: for ye are not my people, and I will not be your Elohim (God).* (Hosea 1:9)

*Yet the number of the children of Yashar'el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God).* (Hosea 1:10)

So why does he call her a dog, and why is the bread withheld? Because the house she belongs to was put away:

*And I saw, when for all the causes whereby backsliding Yashar'el (Israel) committed adultery I had put her away, and given her a bill of divorce; yet her treacherous sister Yahudah (Judah) feared not, but went and played the harlot also.* (Jeremiah 3:8)

And the Torah he gave does not let a husband take back the wife he has put away:

*Her former husband, which sent her away, may not take her again to be his wife, after that she is defiled; for that is abomination before Yahuah (LORD): and thou shalt not cause the land to sin, which Yahuah Elohayka (the LORD thy God) giveth thee for an inheritance.* (Deuteronomy 24:4)

A woman is bound to her husband as long as he lives, and only a death frees her to be married again:

*For the woman which hath an husband is bound by the law to her husband so long as he liveth; but if the husband be dead, she is loosed from the law of her husband.* (Romans 7:2)

*Wherefore, my brethren, ye also are become dead to the law by the body of Messiah (Christ); that ye should be married to another, even to him who is raised from the dead, that we should bring forth fruit unto Elohim (God).* (Romans 7:4)

He has not died yet. The divorced house cannot be seated at his table while he lives as that husband, so the bread is the children's, the undivorced house of Yahudah (Judah), and the scattered are what we became out there, dogs under the table. Mark keeps the word that carries the timing:

*But Yahusha (Jesus) said unto her, Let the children first be filled: for it is not meet to take the children’s bread, and to cast it unto the dogs.* (Mark 7:27)

First. Not never. She hears the order and does not argue it. She asks for what falls from the table now, and he calls that faith great. The redeeming of the house that was put away comes on the other side of his death, and Hosea says how it ends:

*And I will sow her unto me in the earth; and I will have mercy upon her that had not obtained mercy; and I will say to them which were not my people, Thou art my people; and they shall say, Thou art my Elohim (God).* (Hosea 2:23)

The order of the sending shows the same two halves. Before the death, *go not into the way of the Gentiles*; after it:

*Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* (Matthew 28:19)

Not a new people added to the house, but the same house sought in every place it was scattered to, once the death that frees it had been died. Matthew 15 does not say the death is the reason; Deuteronomy, Romans and Mark's *first* say it, line upon line. The woman of Canaan is a woman from that land and a sheep of the house, revealed by her hearing, given the crumbs before her time and the table after it.$n$);

DO $s499c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s499c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, sc.chapter_number AS sch, sv.verse_number AS svn, sb.slug AS sbook, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S499c: card % is gone', r.id; END IF;
    IF x.sbook <> 'matthew' OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S499c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S499c: live text of matthew %:% differs from the read-back this migration was written against — re-dump and rebuild', r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S499c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S499c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s499c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S499c: thread 30911 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s499c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S499c: thread 30911 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s499c$;

DO $s499c2$
DECLARE n_notes int; n_m int; n_t int;
BEGIN
  UPDATE cross_references xr SET note = c.new_note FROM s499c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s499c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s499c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary;
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S499c (matthew 15 canaanite) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %',
    n_notes, (SELECT count(*) FROM s499c_cards) - n_notes, n_m, (SELECT count(*) FROM s499c_cards) - n_m, n_t, 1 - n_t;
END $s499c2$;
COMMIT;
